// File adapter: metadata stays in the store; small binaries expire with this tab.
async function selectedFileMetadata(file) {
 const metadata={fileName:file.name,fileSize:file.size,fileMime:file.type,fileRef:"",fileToken:""};
 if(file.size<=2*1024*1024 && ["application/pdf","image/png","image/jpeg","image/webp"].includes(file.type)) {
  try {const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const token=crypto.randomUUID();sessionStorage.setItem(`bayani.file.${token}`,data);metadata.fileToken=token;}catch(_){toast("File bytes could not be kept in this tab. Only metadata will be saved.","warning");}
 }
 return metadata;
}
const content = document.getElementById("app-content");
const page = document.body.dataset.page;
const itemId = document.body.dataset.itemId;
const isArchivedWorkspace = () => page === "archived-materials" || /^\/(?:admin|contributor)\/archived\/?$/.test(location.pathname);
let repositoryPage = 1;

async function enhanceFilePreview(backend) {
 const viewer=content.querySelector('.file-preview-viewer');
 if(!viewer)return;
 try {
  if(backend.format==='docx') {
   const [{renderAsync}]=await Promise.all([import('docx-preview')]);
   const host=document.createElement('div');host.className='docx-rendered-content';host.setAttribute('aria-label','DOCX document preview');viewer.querySelector('.alert')?.remove();viewer.append(host);
   const response=await fetch(backend.download_url);if(!response.ok)throw new Error('Preview unavailable');
   await renderAsync(await response.arrayBuffer(),host,undefined,{inWrapper:false,ignoreWidth:false,ignoreHeight:false,breakPages:true,experimental:false});
  } else if(backend.format==='xlsx') {
   const [{default:ExcelJS}]=await Promise.all([import('exceljs')]);
   const host=document.createElement('div');host.className='spreadsheet-browser-render';viewer.querySelector('.alert')?.remove();viewer.append(host);
   const response=await fetch(backend.download_url);if(!response.ok)throw new Error('Preview unavailable');
   await renderXlsxDocument(response.arrayBuffer(),ExcelJS,host);
  } else if(backend.format==='pdf') {
   const [pdfjs,worker]=await Promise.all([import('pdfjs-dist'),import('pdfjs-dist/build/pdf.worker.min.mjs?url')]);
   pdfjs.GlobalWorkerOptions.workerSrc=worker.default;
   const host=document.createElement('div');host.className='panel p-2 pdf-preview-host';host.setAttribute('aria-label','PDF page preview');viewer.querySelector('.alert')?.remove();viewer.append(host);
   await renderPdfDocument(backend.preview_url,pdfjs,host);
  }
 } catch(error) {
  const host=viewer.querySelector('.docx-rendered-content,.spreadsheet-browser-render,.pdf-preview-host')||viewer;
  host.textContent='The file preview could not be rendered in this browser. Use Download original.';
 }
}
let repositoryLayout = store.systemSettings().defaultDisplay || "grid";
const esc = (v) => String(v ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const title = (kicker, heading, intro, action = "") => `<header class="bayani-page-heading d-flex flex-column flex-md-row justify-content-between align-items-md-end gap-3 mb-4"><div><div class="eyebrow mb-2">${kicker}</div><h1 class="page-title h2 mb-1">${heading}</h1><p class="text-secondary mb-0">${intro}</p></div>${action}</header>`;
