function savedThemePreference() {
 const themeManager = window.BayaniTheme;
 if (themeManager && typeof themeManager.preference === "function") {
  const preference = themeManager.preference();
  if (["light", "dark", "system"].includes(preference)) return preference;
 }
 return store.preferences().theme || "light";
}
let lastSavedThemePreference = savedThemePreference();
function applyTheme(preference) {
 const themeManager = window.BayaniTheme;
 const selected = preference || savedThemePreference();
 return themeManager && typeof themeManager.apply === "function" ? themeManager.apply(selected) : "light";
}
