async function shareMaterial(id){const material=store.find(id);if(material?.status!=="Approved")return;const url=new URL(`/materials/${encodeURIComponent(id)}`,location.origin).href;try{if(navigator.share){await navigator.share({title:material.title,url});return;}if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);toast("Link copied. This prototype record is available only in browsers that hold its local data.");return;}}catch(error){if(error.name==="AbortError")return;}window.prompt("Copy this material URL. The record is local to this browser:",url);}
function renderResults(){const host=document.getElementById("material-results");if(!host)return;const q=(document.getElementById("search-query")?.value||"").trim().toLowerCase(),f={category:document.getElementById("filter-category")?.value||"",};const list=approved().filter(m=>[m.title,m.description,m.author].join(" ").toLowerCase().includes(q)&&(!f.category||m.category===f.category));const perPage=Math.max(1,Number(store.systemSettings().materialsPerPage)||9),pages=Math.max(1,Math.ceil(list.length/perPage));repositoryPage=Math.min(repositoryPage,pages);const start=(repositoryPage-1)*perPage,visible=list.slice(start,start+perPage);document.getElementById("result-count").textContent=`${list.length} approved ${list.length===1?"material":"materials"} found`;host.innerHTML=list.length?visible.map(m=>card(m,repositoryLayout==="list")).join(""):empty("bi-search",approved().length?"No materials match those filters":"No materials available yet","Change your search or clear the filters.",`<button type="button" class="btn btn-outline-primary mt-3" data-empty-reset>Clear search and filters</button>`);const indicator=document.getElementById("page-indicator");if(indicator)indicator.textContent=list.length?`Page ${repositoryPage} of ${pages} &middot; ${perPage} per page`:"";const previous=document.getElementById("previous-page"),next=document.getElementById("next-page");if(previous)previous.disabled=repositoryPage<=1;if(next)next.disabled=repositoryPage>=pages;document.querySelectorAll("[data-repository-layout]").forEach(button=>button.classList.toggle("active",button.dataset.repositoryLayout===repositoryLayout));hydrateThumbnails(host,store);}
function listPage(key, heading, icon){const listKey={category:"categories"}[key],label={category:"category"}[key];const state=store.get();return shell("admin",heading,`Manage demo ${label} values. Referenced values cannot be removed.`, `<div class="panel p-4"><form id="add-list-form" data-list="${listKey}" class="row g-2 mb-3"><div class="col"><input name="value" required class="form-control" placeholder="New ${label}"></div><div class="col-auto"><button class="btn btn-primary">Add</button></div></form>${state[listKey].map(value=>`<div class="list-group-item d-flex justify-content-between"><span>${esc(value)} &middot; ${store.materials().filter(m=>m[key]===value).length} linked</span><span><button class="btn btn-sm btn-light" data-edit-list="${listKey}" data-value="${esc(value)}">Edit</button> <button class="btn btn-sm btn-outline-danger" data-delete-list="${listKey}" data-value="${esc(value)}">Delete</button></span></div>`).join("")}</div>`);}
function uploadForm(item=null){const d=store.get(),editing=!!item,isDraft=new URLSearchParams(location.search).get("draft")==="1"||item?.status==="Draft";return shell("contributor",editing?"Edit material":isDraft?"Create a draft":"Submit an educational resource","Complete the metadata. Files are temporary; only metadata is stored.",`<form id="submission-form" class="panel p-4" data-edit-id="${editing?esc(item.id):""}" data-is-draft="${isDraft}" novalidate><div class="alert alert-info">A selected file is not uploaded. Drafts stay out of review until submitted.</div>${[["Basic information",[["title","Title","text",item?.title||"",true],["description","Description","textarea",item?.description||"",true],["category","Category","select",item?.category||"",true]]],["Contributor information",[["author","Contributor name","text",item?.author||profile().name,true]]],["File selection",[["fileType","File type","filetype",item?.fileType||"PDF",true]]]].map(([section,fields])=>`<section class="form-section"><h2 class="h5">${section}</h2><div class="row g-3">${fields.map(([name,label,type,value,required])=>`<div class="col-md-6"><label class="form-label">${label}${required?" *":""}</label>${type==="textarea"?`<textarea class="form-control" name="${name}" ${required?"required":""}>${esc(value)}</textarea>`:type==="select"?`<select class="form-select" name="${name}" required><option value="">Choose...</option>${d[{category:"categories"}[name]].map(v=>`<option ${v===value?"selected":""}>${esc(v)}</option>`).join("")}</select>`:type==="filetype"?`<select class="form-select" name="fileType"><option ${value==="PDF"?"selected":""}>PDF</option><option ${value==="Image"?"selected":""}>Image</option><option ${value==="Document"?"selected":""}>Document</option></select>`:`<input class="form-control" name="${name}" value="${esc(value)}" ${required?"required":""}>`}</div>`).join("")}</div></section>`).join("")}<section class="form-section"><h2 class="h5">File selection (optional)</h2><input class="form-control" type="file" id="attachment" accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.odt"><div id="file-info" class="form-text">PDF, image, or document &middot; max ${esc(store.systemSettings().maxUploadMb)} MB. PDF and images up to 2 MB can be previewed in this tab; other files retain metadata only.</div></section><div class="d-flex gap-2"><button type="submit" class="btn btn-primary">${editing?(isDraft?"Save draft":"Save and resubmit"):isDraft?"Save draft":"Submit for review"}</button>${!editing&&!isDraft?`<button type="button" class="btn btn-outline-primary" data-save-draft>Save as draft</button>`:""}<a href="/contributor/submissions" class="btn btn-light border">Cancel</a></div></form>`);}
function filterUsers(){const q=(document.getElementById("user-search")?.value||"").toLowerCase(),roleFilter=document.getElementById("user-role-filter")?.value||"";const rows=[...document.querySelectorAll("#users-table tbody tr[data-user-role]")];rows.forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q)||!!(roleFilter&&row.dataset.userRole!==roleFilter));let message=document.getElementById("users-no-results");if(!message){message=document.createElement("p");message.id="users-no-results";message.className="text-secondary p-3";message.setAttribute("role","status");document.getElementById("users-table")?.parentElement.after(message);}message.textContent="No users match these filters.";message.hidden=!store.users().length||rows.some(row=>!row.hidden);}
