document.addEventListener("change", e=>{if(e.target.id==="profile-avatar"){const f=e.target.files?.[0];if(!f)return;if(!["image/png","image/jpeg","image/webp"].includes(f.type)||f.size>10*1024*1024){e.target.value="";toast("Choose a PNG, JPG/JPEG, or WEBP image no larger than 10 MB.","warning");return;}const reader=new FileReader();reader.onload=()=>{window.bayaniAvatarDraft=reader.result;document.getElementById("avatar-help").textContent=`Selected ${f.name}; saved only when profile changes are saved.`;const remove=document.getElementById("remove-profile-avatar");if(remove)remove.disabled=false;};reader.onerror=()=>toast("Could not read this image. Try a smaller file.","danger");reader.readAsDataURL(f);}});
