 if(form.id==="account-settings-form"){const notifications={submission:form.elements["pref-submission"].checked,decisions:form.elements["pref-decisions"].checked,announcements:form.elements["pref-announcements"].checked};if(!store.updateAccount(role(),{name:values.name,email:values.email,organization:values.organization,contact:values.contact},{theme:values.theme||"light",notifications}))return;lastSavedThemePreference=values.theme||"light";const themeManager=window.BayaniTheme;if(themeManager&&typeof themeManager.save==="function")themeManager.save(values.theme);applyTheme(values.theme);syncHeader();toast("Account settings saved.");return;}
 if(form.id==="system-settings-form"){if(!values.allowedTypes.trim()){toast("Specify at least one allowed extension.","warning");return;}values.materialsPerPage=Number(values.materialsPerPage);values.maxUploadMb=Number(values.maxUploadMb);values.announcementEnabled=form.elements.announcementEnabled.checked;if(!store.updateSystemSettings(values)){toast("Could not save system settings; browser storage may be unavailable.","danger");return;}syncHeader();toast("Demo system settings updated.");return;}
